import type { Enforcement } from '../enforcement.js';
import type { Domain, KnowledgeUnit } from '../schema/knowledge-unit.js';

/**
 * Filter for exact rule matching (deterministic search).
 */
export interface RuleFilter {
  /** Filter by domain */
  domain?: Domain;

  /**
   * Filter by brand (use null for global rules only).
   * "shared" and "global" are treated as sentinels meaning always-include,
   * equivalent to a missing brand (null/undefined).
   */
  brand?: string | null;

  /** Filter by enforcement levels */
  enforcement?: Enforcement[];

  /** Filter by kind (e.g., 'rule', 'glossary', 'rubric') */
  kind?: string;

  /** Filter by tags (all must match) */
  tags?: string[];

  /** Full-text search on title and body */
  textQuery?: string;
}

/**
 * Options for semantic (vector) search.
 */
export interface SemanticSearchOptions {
  /** Filter by domain before searching */
  domain?: Domain;

  /** Filter by brand before searching */
  brand?: string;

  /** Filter by minimum enforcement level */
  minEnforcement?: Enforcement;

  /** Maximum number of results to return */
  limit?: number;

  /** Minimum similarity score (0-1) */
  minScore?: number;
}

/**
 * A knowledge unit with its similarity score from semantic search.
 */
export interface ScoredKnowledgeUnit {
  /** The matching knowledge unit */
  unit: KnowledgeUnit;

  /** Similarity score from 0-1 (1 = exact match) */
  score: number;
}

/**
 * SearchAdapter defines the interface for searching knowledge units.
 * Supports both deterministic (exact) matching and semantic (vector) search.
 */
export interface SearchAdapter {
  /**
   * Exact match search using filters.
   * Returns all knowledge units matching the specified criteria.
   */
  exactMatch(filter: RuleFilter): Promise<KnowledgeUnit[]>;

  /**
   * Semantic search using vector similarity.
   * Returns knowledge units ranked by relevance to the query.
   */
  semanticSearch(
    query: string,
    options?: SemanticSearchOptions,
  ): Promise<ScoredKnowledgeUnit[]>;
}

/**
 * BYOK LLM completion function factory.
 *
 * Creates an LlmCompletionFn from provider config, using raw fetch (no SDK).
 * Mirrors the topology BYOK pattern for embeddings.
 */

import type { LlmCompletionFn } from '../propose.js';

export interface CompletionProviderOptions {
  provider: 'openai' | 'anthropic';
  apiKey: string;
  model?: string;
  baseUrl?: string;
}

/**
 * Create an LlmCompletionFn from BYOK provider config.
 */
export function createCompletionFn(opts: CompletionProviderOptions): LlmCompletionFn {
  switch (opts.provider) {
    case 'openai':
      return createOpenAICompletionFn(opts);
    case 'anthropic':
      return createAnthropicCompletionFn(opts);
    default:
      throw new Error(`Unsupported LLM provider: ${opts.provider}`);
  }
}

function createOpenAICompletionFn(opts: CompletionProviderOptions): LlmCompletionFn {
  const baseUrl = opts.baseUrl || 'https://api.openai.com';
  const model = opts.model || 'gpt-4o-mini';

  return async (prompt: string): Promise<string> => {
    const res = await fetch(`${baseUrl}/v1/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${opts.apiKey}`,
      },
      body: JSON.stringify({
        model,
        messages: [{ role: 'user', content: prompt }],
        max_tokens: 4096,
      }),
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`OpenAI API error ${res.status}: ${text}`);
    }

    const data = (await res.json()) as { choices: Array<{ message: { content: string } }> };
    return data.choices[0]?.message?.content ?? '';
  };
}

function createAnthropicCompletionFn(opts: CompletionProviderOptions): LlmCompletionFn {
  const model = opts.model || 'claude-sonnet-4-20250514';

  return async (prompt: string): Promise<string> => {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': opts.apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model,
        max_tokens: 4096,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!res.ok) {
      const text = await res.text();
      throw new Error(`Anthropic API error ${res.status}: ${text}`);
    }

    const data = (await res.json()) as { content: Array<{ type: string; text: string }> };
    const textBlock = data.content.find((b) => b.type === 'text');
    return textBlock?.text ?? '';
  };
}

import type { ScoredKnowledgeUnit } from '../adapters/search.js';
import type { KnowledgeUnit } from '../schema/index.js';

/**
 * Options for the BM25 index.
 */
export interface BM25Options {
  /** Term frequency saturation parameter (default: 1.2) */
  k1?: number;
  /** Document length normalization (default: 0.75) */
  b?: number;
  /** Weight multiplier for title terms (default: 2.0) */
  titleBoost?: number;
  /** Weight multiplier for tag terms (default: 1.5) */
  tagBoost?: number;
}

/**
 * Common English stop words filtered during tokenization.
 */
const STOP_WORDS = new Set([
  'a',
  'an',
  'and',
  'are',
  'as',
  'at',
  'be',
  'by',
  'for',
  'from',
  'has',
  'he',
  'in',
  'is',
  'it',
  'its',
  'of',
  'on',
  'that',
  'the',
  'to',
  'was',
  'will',
  'with',
  'this',
  'but',
  'they',
  'have',
  'had',
  'what',
  'when',
  'where',
  'who',
  'which',
  'why',
  'how',
  'all',
  'each',
  'every',
  'both',
  'few',
  'more',
  'most',
  'other',
  'some',
  'such',
  'no',
  'nor',
  'not',
  'only',
  'own',
  'same',
  'so',
  'than',
  'too',
  'very',
  'can',
  'just',
  'should',
  'now',
  'also',
  'been',
  'being',
  'do',
  'does',
  'did',
  'doing',
  'would',
  'could',
  'ought',
  'am',
  'were',
  'if',
  'or',
  'because',
  'about',
  'into',
  'through',
  'during',
  'before',
  'after',
  'above',
  'below',
  'between',
  'out',
  'off',
  'over',
  'under',
  'again',
  'then',
  'once',
  'here',
  'there',
  'these',
  'those',
  'up',
  'down',
]);

/**
 * Minimal English stemmer — strips common suffixes so that
 * "errors" matches "error", "messages" matches "message", etc.
 * Conservative: only applies when the resulting stem is >= 3 chars.
 */
function stem(word: string): string {
  if (word.length <= 3) return word;
  // ies → y (utilities → utility)
  if (word.endsWith('ies') && word.length > 5) return `${word.slice(0, -3)}y`;
  // ness → (awareness → aware)
  if (word.endsWith('ness') && word.length > 6) return word.slice(0, -4);
  // ing → (writing → writ, but keep stem >= 3 chars)
  if (word.endsWith('ing') && word.length > 5) {
    const s = word.slice(0, -3);
    if (s.length >= 3) return s;
  }
  // ed → (failed → fail)
  if (word.endsWith('ed') && word.length > 4) return word.slice(0, -2);
  // es → (errors → error, matches → match)
  if (word.endsWith('es') && word.length > 4) return word.slice(0, -2);
  // s → (buttons → button, guidelines → guideline)
  if (word.endsWith('s') && word.length > 3) return word.slice(0, -1);
  return word;
}

/**
 * Tokenize text into lowercase stems, filtering stop words and short tokens.
 */
export function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .split(/\W+/)
    .filter((t) => t.length >= 2 && !STOP_WORDS.has(t))
    .map(stem);
}

/** Internal document representation for the BM25 index. */
interface IndexedDoc {
  unitId: string;
  /** Weighted term frequencies (title terms get titleBoost, tag terms get tagBoost) */
  termFreqs: Map<string, number>;
  /** Total weighted term count (used as document length) */
  length: number;
}

/**
 * BM25 full-text search index over KnowledgeUnit arrays.
 *
 * Zero dependencies. Operates entirely in memory.
 * Suitable for corpora of tens to low thousands of units.
 */
export class BM25Index {
  private readonly k1: number;
  private readonly b: number;
  private readonly titleBoost: number;
  private readonly tagBoost: number;

  private docs: IndexedDoc[] = [];
  private unitMap = new Map<string, number>(); // unitId → docs index
  private units: KnowledgeUnit[] = [];

  /** Number of documents containing each term */
  private docFreq = new Map<string, number>();
  /** Average document length across corpus */
  private avgdl = 0;

  constructor(units: KnowledgeUnit[], options?: BM25Options) {
    this.k1 = options?.k1 ?? 1.2;
    this.b = options?.b ?? 0.75;
    this.titleBoost = options?.titleBoost ?? 2.0;
    this.tagBoost = options?.tagBoost ?? 1.5;

    for (const unit of units) {
      this.addInternal(unit);
    }
    this.recomputeGlobals();
  }

  /** Number of indexed documents. */
  get size(): number {
    return this.docs.length;
  }

  /**
   * Add a unit to the index. Rebuilds global stats (IDF, avgdl).
   */
  add(unit: KnowledgeUnit): void {
    this.addInternal(unit);
    this.recomputeGlobals();
  }

  /**
   * Search the index, returning units ranked by BM25 score.
   */
  search(query: string, limit = 10): ScoredKnowledgeUnit[] {
    const queryTerms = tokenize(query);
    if (queryTerms.length === 0 || this.docs.length === 0) return [];

    const scores: Array<{ idx: number; score: number }> = [];

    for (let i = 0; i < this.docs.length; i++) {
      const s = this.scoreDoc(queryTerms, i);
      if (s > 0) {
        scores.push({ idx: i, score: s });
      }
    }

    scores.sort((a, b) => b.score - a.score);

    return scores.slice(0, limit).map(({ idx, score }) => ({
      unit: this.units[idx],
      score,
    }));
  }

  /**
   * Score a specific unit against a query. Returns 0 if unit not in index.
   */
  score(query: string, unitId: string): number {
    const idx = this.unitMap.get(unitId);
    if (idx === undefined) return 0;
    const queryTerms = tokenize(query);
    if (queryTerms.length === 0) return 0;
    return this.scoreDoc(queryTerms, idx);
  }

  // --- internals ---

  private addInternal(unit: KnowledgeUnit): void {
    if (this.unitMap.has(unit.id)) return; // no duplicates

    const termFreqs = new Map<string, number>();

    // Title terms with boost
    for (const t of tokenize(unit.title)) {
      termFreqs.set(t, (termFreqs.get(t) ?? 0) + this.titleBoost);
    }

    // Body terms at 1x
    for (const t of tokenize(unit.body)) {
      termFreqs.set(t, (termFreqs.get(t) ?? 0) + 1);
    }

    // Tag terms with boost
    for (const tag of unit.tags) {
      for (const t of tokenize(tag)) {
        termFreqs.set(t, (termFreqs.get(t) ?? 0) + this.tagBoost);
      }
    }

    let length = 0;
    for (const freq of termFreqs.values()) {
      length += freq;
    }

    const idx = this.docs.length;
    this.docs.push({ unitId: unit.id, termFreqs, length });
    this.units.push(unit);
    this.unitMap.set(unit.id, idx);
  }

  private recomputeGlobals(): void {
    // Recompute document frequencies
    this.docFreq.clear();
    for (const doc of this.docs) {
      for (const term of doc.termFreqs.keys()) {
        this.docFreq.set(term, (this.docFreq.get(term) ?? 0) + 1);
      }
    }

    // Recompute average document length
    if (this.docs.length === 0) {
      this.avgdl = 0;
    } else {
      let totalLength = 0;
      for (const doc of this.docs) {
        totalLength += doc.length;
      }
      this.avgdl = totalLength / this.docs.length;
    }
  }

  private scoreDoc(queryTerms: string[], docIdx: number): number {
    const doc = this.docs[docIdx];
    const N = this.docs.length;
    let total = 0;

    for (const term of queryTerms) {
      const tf = doc.termFreqs.get(term) ?? 0;
      if (tf === 0) continue;

      const n = this.docFreq.get(term) ?? 0;

      // IDF with +1 to prevent negative values for high-frequency terms
      const idf = Math.log((N - n + 0.5) / (n + 0.5) + 1);

      // BM25 term score
      const numerator = tf * (this.k1 + 1);
      const denominator =
        tf + this.k1 * (1 - this.b + this.b * (doc.length / this.avgdl));

      total += idf * (numerator / denominator);
    }

    return total;
  }
}

/**
 * Madrigal MCP Server
 *
 * Serves compiled knowledge over the Model Context Protocol (MCP).
 * Enables AI assistants (Claude, Cursor, Goose) to search, query, and
 * review content against knowledge units.
 *
 * Requires: @modelcontextprotocol/sdk and zod as peer dependencies.
 */

import { existsSync, readFileSync } from 'node:fs';
import type { MadrigalConfig } from '../config.js';
import { loadConfig } from '../config.js';
import {
  type Enforcement,
  effectiveEnforcement,
  enforcementRank,
} from '../enforcement.js';
import { loadKnowledge } from '../loader.js';
import type { KnowledgeUnit } from '../schema/index.js';
import { BM25SearchAdapter } from '../search/adapter.js';

/**
 * Options for starting the MCP server.
 */
export interface ServeOptions {
  /** MCP server name shown to clients (default: 'madrigal') */
  name?: string;
  /** Base directory (defaults to cwd) */
  baseDir?: string;
  /** Path to a pre-built JSON bundle — skips build if provided */
  bundlePath?: string;
  /** Paths to additional pre-built JSON bundles to merge with bundlePath */
  bundlePaths?: string[];
  /** Path to madrigal config file */
  configPath?: string;
  /** Anthropic API key for review_content LLM synthesis (falls back to ANTHROPIC_API_KEY env var) */
  anthropicApiKey?: string;
  /** Claude model to use for review_content (default: claude-sonnet-4-6) */
  model?: string;
  /** Custom system prompt for review_content LLM synthesis. Overrides the default generic prompt. */
  reviewSystemPrompt?: string;
}

/**
 * Start the Madrigal MCP server over stdio.
 *
 * Loads knowledge units (from bundle or by running the build pipeline),
 * creates a BM25 search index, and exposes tools for searching, querying,
 * and reviewing content against the knowledge base.
 */
// "shared" and "global" are sentinel values meaning always-include,
// equivalent to a missing brand (null/undefined).
const isGlobal = (b: string | undefined | null): boolean =>
  !b || b === 'shared' || b === 'global';

const EXCERPT_CHARS = 2000;
const DEFAULT_MODEL = 'claude-sonnet-4-6';

export async function serveMcp(options: ServeOptions = {}): Promise<void> {
  // Dynamic imports for optional peer dependencies
  let McpServer: typeof import('@modelcontextprotocol/sdk/server/mcp.js').McpServer;
  let StdioServerTransport: typeof import('@modelcontextprotocol/sdk/server/stdio.js').StdioServerTransport;
  let z: typeof import('zod');

  try {
    ({ McpServer } = await import('@modelcontextprotocol/sdk/server/mcp.js'));
    ({ StdioServerTransport } = await import(
      '@modelcontextprotocol/sdk/server/stdio.js'
    ));
    z = await import('zod');
  } catch {
    console.error(
      'Missing dependencies for "madrigal serve".\n' +
        'Install them with: npm install @modelcontextprotocol/sdk zod',
    );
    process.exit(1);
  }

  // Optional Anthropic client for review_content synthesis
  let anthropic: import('@anthropic-ai/sdk').Anthropic | null = null;
  const apiKey = [REDACTED] ?? process.env.ANTHROPIC_API_KEY;
  if (apiKey) {
    try {
      const { default: Anthropic } = await import('@anthropic-ai/sdk');
      anthropic = new Anthropic({ apiKey });
    } catch {
      console.error(
        'Warning: @anthropic-ai/sdk not installed. review_content will return a raw prompt.\n' +
          'Install with: npm install @anthropic-ai/sdk',
      );
    }
  }

  const baseDir = options.baseDir ?? process.cwd();

  // Load units + config
  const { units } = await loadUnits(options, baseDir);

  if (units.length === 0) {
    console.error(
      'No knowledge units found. Run "madrigal build" first or check your config.',
    );
    process.exit(1);
  }

  // Build search adapter
  const search = new BM25SearchAdapter(units);

  // Create MCP server
  const server = new McpServer({
    name: options.name ?? 'madrigal',
    version: '0.1.0',
  });

  // --- Tool: search_knowledge ---
  server.tool(
    'search_knowledge',
    'Search the knowledge base by query text, tags, domain, enforcement, kind, or brand. Returns matching rules, guidelines, and patterns ranked by relevance.',
    {
      query: z
        .string()
        .optional()
        .describe('Free text search across titles and body content'),
      domain: z.string().optional().describe('Filter by domain'),
      brand: z.string().optional().describe('Filter by brand (omit for all)'),
      enforcement: z
        .array(z.enum(['must', 'should', 'may', 'context', 'deprecated']))
        .optional()
        .describe('Filter by enforcement levels'),
      kind: z
        .string()
        .optional()
        .describe('Filter by kind (e.g. rule, glossary, rubric)'),
      tags: z.array(z.string()).optional().describe('Filter by tags'),
      limit: z.number().optional().describe('Max results (default: 10)'),
    },
    async ({ query, domain, brand, enforcement, kind, tags, limit }) => {
      let results: KnowledgeUnit[];

      if (query) {
        const scored = await search.semanticSearch(query, {
          domain,
          brand,
          minEnforcement: enforcement?.[enforcement.length - 1], // least strict as min
          limit: limit ?? 10,
        });
        // Post-filter by kind and tags if specified
        let filtered = scored;
        if (kind) filtered = filtered.filter((r) => r.unit.kind === kind);
        if (tags && tags.length > 0) {
          filtered = filtered.filter((r) =>
            tags.some((t) => r.unit.tags.includes(t)),
          );
        }
        results = filtered.map((r) => r.unit);
      } else {
        results = await search.exactMatch({
          domain,
          brand,
          enforcement: enforcement as Enforcement[] | undefined,
          kind,
          tags,
        });
        results = results.slice(0, limit ?? 10);
      }

      if (results.length === 0) {
        return {
          content: [
            {
              type: 'text' as const,
              text: 'No matching knowledge units found.',
            },
          ],
        };
      }

      const lines = results.map((u) => {
        const tags = u.tags.length ? ` (${u.tags.slice(0, 3).join(', ')})` : '';
        const enforcement = effectiveEnforcement(u.enforcement);
        // Include a short excerpt from the body (first 150 chars) for context
        const excerpt = u.body
          .replace(/^#+\s+/gm, '')
          .replace(/\n+/g, ' ')
          .trim()
          .slice(0, 150);
        return `- [${enforcement.toUpperCase()}] **${u.id}**${tags}\n  ${u.title}${excerpt ? `\n  _${excerpt}…_` : ''}`;
      });

      return {
        content: [
          {
            type: 'text' as const,
            text: `Found ${results.length} result(s):\n\n${lines.join('\n\n')}\n\nUse get_knowledge_unit(id) to read the full content of any result.`,
          },
        ],
      };
    },
  );

  // --- Tool: get_knowledge_unit ---
  server.tool(
    'get_knowledge_unit',
    'Get a specific knowledge unit by its ID. Returns the full rule/guideline with all metadata.',
    {
      id: z.string().describe('The knowledge unit ID'),
    },
    async ({ id }) => {
      const unit = units.find((u) => u.id === id);
      if (!unit) {
        return {
          content: [
            {
              type: 'text' as const,
              text: `No knowledge unit found with ID "${id}". Available IDs: ${units.map((u) => u.id).join(', ')}`,
            },
          ],
        };
      }

      const meta = [
        `**ID:** ${unit.id}`,
        unit.domain ? `**Domain:** ${unit.domain}` : null,
        `**Kind:** ${unit.kind}`,
        `**Enforcement:** ${effectiveEnforcement(unit.enforcement)}`,
        `**Tags:** ${unit.tags.join(', ')}`,
        unit.brand ? `**Brand:** ${unit.brand}` : null,
        unit.system ? `**System:** ${unit.system}` : null,
        `**Origin:** ${unit.provenance.origin} (confidence: ${unit.provenance.confidence})`,
      ]
        .filter(Boolean)
        .join('\n');

      return {
        content: [
          {
            type: 'text' as const,
            text: `# ${unit.title}\n\n${meta}\n\n---\n\n${unit.body}`,
          },
        ],
      };
    },
  );

  // --- Tool: list_knowledge_units ---
  server.tool(
    'list_knowledge_units',
    'List all available knowledge units with their IDs, titles, enforcement, and tags. Useful for discovering what rules exist.',
    {
      domain: z.string().optional().describe('Filter by domain'),
      brand: z.string().optional().describe('Filter by brand'),
      enforcement: z
        .enum(['must', 'should', 'may', 'context', 'deprecated'])
        .optional()
        .describe('Filter by enforcement level'),
    },
    async ({ domain, brand, enforcement }) => {
      let filtered = [...units];
      if (domain) filtered = filtered.filter((u) => u.domain === domain);
      if (brand)
        filtered = filtered.filter(
          (u) => isGlobal(u.brand) || u.brand === brand,
        );
      if (enforcement)
        filtered = filtered.filter(
          (u) => effectiveEnforcement(u.enforcement) === enforcement,
        );

      filtered.sort(
        (a, b) =>
          enforcementRank(a.enforcement) - enforcementRank(b.enforcement),
      );

      const text = filtered
        .map(
          (u) =>
            `- **${u.id}** [${effectiveEnforcement(u.enforcement).toUpperCase()}]: ${u.title} (${u.tags.join(', ')})`,
        )
        .join('\n');

      return {
        content: [
          {
            type: 'text' as const,
            text: `${filtered.length} knowledge unit(s):\n\n${text}`,
          },
        ],
      };
    },
  );

  // --- Tool: get_brand_rules ---
  server.tool(
    'get_brand_rules',
    'List all knowledge units for a specific brand, sorted by enforcement. Returns an index of IDs, titles, and enforcement levels. Use get_knowledge_unit(id) to read a full unit.',
    {
      brand: z.string().describe('Brand name'),
    },
    async ({ brand }) => {
      // Filter to units for this brand (including shared/global units)
      const brandUnits = units.filter(
        (u) => isGlobal(u.brand) || u.brand === brand,
      );

      if (brandUnits.length === 0) {
        const availableBrands = [
          ...new Set(units.map((u) => u.brand).filter(Boolean)),
        ];
        return {
          content: [
            {
              type: 'text' as const,
              text: `No units found for brand "${brand}". Available brands: ${availableBrands.join(', ')}`,
            },
          ],
        };
      }

      // Sort by enforcement (must first), then title
      brandUnits.sort(
        (a, b) =>
          enforcementRank(a.enforcement) - enforcementRank(b.enforcement) ||
          a.title.localeCompare(b.title),
      );

      const lines = brandUnits.map(
        (u) =>
          `- [${effectiveEnforcement(u.enforcement).toUpperCase()}] **${u.id}** — ${u.title}${u.tags.length ? ` (${u.tags.slice(0, 3).join(', ')})` : ''}`,
      );

      const text = `${brandUnits.length} knowledge unit(s) for brand "${brand}":\n\n${lines.join('\n')}\n\nUse get_knowledge_unit(id) to read the full content of any unit.`;

      return { content: [{ type: 'text' as const, text }] };
    },
  );

  // --- Tool: review_content ---
  server.tool(
    'review_content',
    'Review a piece of content against the knowledge base. Finds applicable rules by content similarity and presents them for compliance review.',
    {
      content: z.string().describe('The content text to review'),
      context: z
        .string()
        .optional()
        .describe(
          'Where this content appears (e.g. "error message", "button label")',
        ),
      brand: z.string().optional().describe('Brand context'),
    },
    async ({ content: contentText, context, brand }) => {
      // Prepend brand to query for natural BM25 weighting — brand is a relevance
      // signal here, not a hard filter, so we search across all units and let
      // the LLM determine cross-brand applicability.
      const brandPrefix = brand ? `${brand} ` : '';
      const query = `${brandPrefix}${context ? `${context} ` : ''}${contentText}`;

      const scored = await search.semanticSearch(query, { limit: 15 });

      if (scored.length === 0) {
        return {
          content: [
            {
              type: 'text' as const,
              text: 'No applicable rules found for this content.',
            },
          ],
        };
      }

      const rulesText = scored
        .map((r) => {
          const brandTag = r.unit.brand ? ` [${r.unit.brand}]` : '';
          const enforcement = effectiveEnforcement(r.unit.enforcement);
          const excerpt =
            r.unit.body.length > EXCERPT_CHARS
              ? `${r.unit.body.slice(0, EXCERPT_CHARS)}\n[…truncated]`
              : r.unit.body;
          return `### ${r.unit.title} [${enforcement.toUpperCase()}]${brandTag}\n**ID:** ${r.unit.id}\n\n${excerpt}`;
        })
        .join('\n\n---\n\n');

      const brandLine = brand ? `\n**Brand context:** ${brand}` : '';
      const contextLine = context ? `\n**Context:** ${context}` : '';

      if (anthropic) {
        const model = options.model ?? DEFAULT_MODEL;
        const message = await anthropic.messages.create({
          model,
          max_tokens: 1024,
          system:
            options.reviewSystemPrompt ??
            `You are a content reviewer. You review content against brand and product guidelines.

The guidelines retrieved may come from different brands or sources. Use judgment to determine whether a guideline applies to the content being reviewed — a guideline from one brand may still be relevant for another if no brand-specific standard exists.

When reviewing content, you:
1. Identify which rules apply to the content based on the guidelines provided
2. State clearly whether the content follows or violates each applicable rule
3. Note the source brand of each guideline when it differs from the content's brand
4. Explain any violations concisely and suggest corrections
5. Flag "must" violations — these are non-negotiable

Format your response as:
- A brief overall assessment (1–2 sentences)
- A bulleted list of findings (rule name, PASS/FAIL/WARN/N/A, brief explanation)
- If violations exist: specific correction suggestions`,
          messages: [
            {
              role: 'user',
              content: `Review this content against the guidelines below.

**Content:** "${contentText}"${contextLine}${brandLine}

**Guidelines retrieved (${scored.length}) — may include shared and cross-brand rules; apply judgment on relevance:**

${rulesText}`,
            },
          ],
        });

        const responseText = (
          message.content as Array<{ type: string; text?: string }>
        )
          .filter((b) => b.type === 'text')
          .map((b) => b.text ?? '')
          .join('');

        return { content: [{ type: 'text' as const, text: responseText }] };
      }

      // Fallback when no Anthropic client is configured: return the raw prompt
      const prompt = `Review this content against the design rules below.

**Content to review:** "${contentText}"${contextLine}${brandLine}

**Applicable rules:**

${rulesText}

For each applicable rule, state whether the content follows it or violates it, with a brief explanation.`;

      return { content: [{ type: 'text' as const, text: prompt }] };
    },
  );

  // Start stdio transport
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

// --- helpers ---

async function loadUnits(
  options: ServeOptions,
  baseDir: string,
): Promise<{ units: KnowledgeUnit[]; config: MadrigalConfig | null }> {
  // Path 1: pre-built JSON bundle(s)
  const allPaths = [
    ...(options.bundlePath ? [options.bundlePath] : []),
    ...(options.bundlePaths ?? []),
  ];

  if (allPaths.length > 0) {
    const allUnits: KnowledgeUnit[] = [];

    for (const bundlePath of allPaths) {
      const absPath = bundlePath.startsWith('/')
        ? bundlePath
        : `${baseDir}/${bundlePath}`;

      if (!existsSync(absPath)) {
        console.error(`Bundle not found: ${absPath}`);
        process.exit(1);
      }

      const bundle = JSON.parse(readFileSync(absPath, 'utf-8')) as {
        units?: KnowledgeUnit[];
      };
      allUnits.push(...(bundle.units ?? []));
    }

    // Try to load config for brand resolution (optional)
    let config: MadrigalConfig | null = null;
    try {
      config = loadConfig(options.configPath);
    } catch {
      // Config not required when serving from bundle
    }

    return { units: allUnits, config };
  }

  // Path 2: load from source files via config
  const config = loadConfig(options.configPath);
  const loadResult = await loadKnowledge({
    sources: config.sources,
    config,
    baseDir,
  });

  return { units: loadResult.units, config };
}

import type {
  RuleFilter,
  ScoredKnowledgeUnit,
  SearchAdapter,
  SemanticSearchOptions,
} from '../adapters/search.js';
import { effectiveEnforcement, enforcementRank } from '../enforcement.js';
import type { KnowledgeUnit } from '../schema/index.js';
import { BM25Index } from './bm25.js';

// "shared" and "global" are sentinel values meaning always-include,
// equivalent to a missing brand (null/undefined).
const isGlobal = (b: string | undefined | null): boolean =>
  !b || b === 'shared' || b === 'global';

/**
 * SearchAdapter implementation backed by an in-memory BM25 index.
 *
 * Provides both deterministic exact-match filtering and BM25-ranked
 * semantic search over KnowledgeUnit arrays. Zero external dependencies.
 */
export class BM25SearchAdapter implements SearchAdapter {
  private readonly units: KnowledgeUnit[];
  private readonly index: BM25Index;

  constructor(units: KnowledgeUnit[]) {
    this.units = units;
    this.index = new BM25Index(units);
  }

  /**
   * Exact-match filtering by metadata fields.
   * If textQuery is provided, results are ranked by BM25 score.
   * Otherwise, results are sorted by enforcement (must first).
   */
  async exactMatch(filter: RuleFilter): Promise<KnowledgeUnit[]> {
    let results = this.applyFilters(this.units, filter);

    if (filter.textQuery) {
      // Build a temporary index over the filtered set for ranking
      const filtered = new BM25Index(results);
      const scored = filtered.search(filter.textQuery, results.length);
      results = scored.map((s) => s.unit);
    } else {
      // Sort by enforcement: must first
      results.sort(
        (a, b) =>
          enforcementRank(a.enforcement) - enforcementRank(b.enforcement),
      );
    }

    return results;
  }

  /**
   * BM25-ranked search with optional metadata post-filtering.
   *
   * Scores are normalized to 0-1 (top result = 1.0).
   * Enforceable rules (must, should) receive a small score boost.
   */
  async semanticSearch(
    query: string,
    options?: SemanticSearchOptions,
  ): Promise<ScoredKnowledgeUnit[]> {
    // Get raw BM25 results (generous limit, we'll filter and trim)
    const rawLimit = Math.max((options?.limit ?? 10) * 3, 50);
    const raw = this.index.search(query, rawLimit);

    if (raw.length === 0) return [];

    // Post-filter by metadata
    let results = raw;

    if (options?.domain) {
      results = results.filter((r) => r.unit.domain === options.domain);
    }

    if (options?.brand) {
      results = results.filter(
        (r) => isGlobal(r.unit.brand) || r.unit.brand === options.brand,
      );
    }

    if (options?.minEnforcement) {
      const minOrder = enforcementRank(options.minEnforcement);
      results = results.filter(
        (r) => enforcementRank(r.unit.enforcement) <= minOrder,
      );
    }

    // Apply enforcement boost: enforceable rules score slightly higher
    results = results.map((r) => {
      let boosted = r.score;
      const enforcement = effectiveEnforcement(r.unit.enforcement);
      if (enforcement === 'must') boosted *= 1.2;
      else if (enforcement === 'should') boosted *= 1.1;
      return { unit: r.unit, score: boosted };
    });

    // Re-sort after boost
    results.sort((a, b) => b.score - a.score);

    // Normalize scores to 0-1
    const maxScore = results[0]?.score ?? 1;
    if (maxScore > 0) {
      results = results.map((r) => ({
        unit: r.unit,
        score: Math.round((r.score / maxScore) * 1000) / 1000,
      }));
    }

    // Apply minScore filter
    if (options?.minScore !== undefined) {
      const minScore = options.minScore;
      results = results.filter((r) => r.score >= minScore);
    }

    // Apply limit
    const limit = options?.limit ?? 10;
    return results.slice(0, limit);
  }

  /** Apply deterministic metadata filters. */
  private applyFilters(
    units: KnowledgeUnit[],
    filter: RuleFilter,
  ): KnowledgeUnit[] {
    let results = [...units];

    if (filter.domain) {
      results = results.filter((u) => u.domain === filter.domain);
    }

    if (filter.brand !== undefined) {
      if (filter.brand === null) {
        // null means global-only
        results = results.filter((u) => !u.brand);
      } else {
        results = results.filter(
          (u) => isGlobal(u.brand) || u.brand === filter.brand,
        );
      }
    }

    if (filter.enforcement && filter.enforcement.length > 0) {
      const allowed = new Set<string>(filter.enforcement);
      results = results.filter((u) =>
        allowed.has(effectiveEnforcement(u.enforcement)),
      );
    }

    if (filter.kind) {
      results = results.filter((u) => u.kind === filter.kind);
    }

    if (filter.tags && filter.tags.length > 0) {
      // All specified tags must be present on the unit
      results = results.filter((u) =>
        filter.tags?.every((t) => u.tags.includes(t)),
      );
    }

    return results;
  }
}

