import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import type { MadrigalConfig } from '../config.js';
import { loadKnowledgeSync } from '../loader.js';
import { build } from '../pipeline.js';

function makeConfig(
  overrides: {
    sources?: string[];
    schema?: Partial<MadrigalConfig['schema']>;
    kinds?: MadrigalConfig['kinds'];
    vocabularies?: MadrigalConfig['vocabularies'];
    platforms?: MadrigalConfig['platforms'];
  } = {},
): MadrigalConfig {
  const schema: MadrigalConfig['schema'] = {
    preserveUnknownFrontmatter: true,
    id: { field: 'id', strategy: 'path' },
    kind: { field: 'type', default: 'record', byPath: {} },
    title: { field: 'title' },
    relationships: { wikilinks: true },
  };

  return {
    sources: overrides.sources || ['context/**/*.md'],
    schema: {
      ...schema,
      ...overrides.schema,
      id: { ...schema.id, ...overrides.schema?.id },
      kind: { ...schema.kind, ...overrides.schema?.kind },
      title: { ...schema.title, ...overrides.schema?.title },
      relationships: {
        ...schema.relationships,
        ...overrides.schema?.relationships,
      },
    },
    vocabularies: overrides.vocabularies || {},
    domains: {},
    kinds: overrides.kinds || {
      record: {},
      study: {
        required: ['title', 'methodology', 'research_period', 'source_url'],
      },
      theme: {},
      competitor: {
        required: ['title', 'competitor_id', 'threat_level'],
      },
    },
    brands: {},
    platforms: overrides.platforms || {},
  };
}

describe('loadKnowledge schema compiler behavior', () => {
  let tempDir: string;

  beforeEach(() => {
    tempDir = mkdtempSync(join(tmpdir(), 'madrigal-loader-'));
  });

  afterEach(() => {
    rmSync(tempDir, { recursive: true, force: true });
  });

  function write(relativePath: string, content: string): void {
    const filePath = join(tempDir, relativePath);
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, content, 'utf-8');
  }

  it('preserves frontmatter, normalizes attributes, maps kinds, and resolves wikilinks', () => {
    write(
      'context/themes/trust.md',
      `---
title: Trust
type: theme
aliases:
  - Confidence
---
Signals that help people feel safe continuing.
`,
    );
    write(
      'context/studies/checkout-trust.md',
      `---
title: Checkout Trust Study
type: study
brand: Old Co
methodology: Interviews
research_period: Q1
source_url: https://example.com/research
durability: Evergreen
---
Participants connected onboarding clarity to [[Trust]] and [[Trust|trusted flows]].
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig({
        vocabularies: {
          brand: { values: ['Acme'], aliases: { 'Old Co': 'Acme' } },
          durability: { values: ['Evergreen', 'Timebound'] },
        },
      }),
      baseDir: tempDir,
    });

    expect(result.errors).toEqual([]);
    expect(result.warnings).toEqual([]);

    const study = result.units.find((unit) => unit.kind === 'study');
    const theme = result.units.find((unit) => unit.kind === 'theme');

    expect(study?.id).toBe('context-studies-checkout-trust');
    expect(study?.frontmatter.brand).toBe('Old Co');
    expect(study?.frontmatter.durability).toBe('Evergreen');
    expect(study?.attributes.brand).toBe('Acme');
    expect(study?.attributes.methodology).toBe('Interviews');
    expect(study?.relationships).toEqual([
      {
        type: 'wikilink',
        target: 'Trust',
        resolved: true,
        targetId: theme?.id,
      },
      {
        type: 'wikilink',
        target: 'Trust',
        label: 'trusted flows',
        resolved: true,
        targetId: theme?.id,
      },
    ]);
  });

  it('uses path-based kind fallback when the configured field is absent', () => {
    write(
      'context/studies/path-mapped.md',
      `---
title: Path Mapped Study
methodology: Survey
research_period: Q2
source_url: https://example.com/survey
---
Body.
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig({
        schema: {
          kind: {
            field: 'type',
            default: 'record',
            byPath: { 'context/studies/**': 'study' },
          },
        },
      }),
      baseDir: tempDir,
    });

    expect(result.errors).toEqual([]);
    expect(result.units[0].kind).toBe('study');
  });

  it('generates path-safe IDs for index files and duplicate filenames', () => {
    write(
      'context/studies/_index.md',
      `---
title: Study Overview
type: record
---
Overview.
`,
    );
    write(
      'context/studies/shared.md',
      `---
title: Shared Name
type: record
---
Study body.
`,
    );
    write(
      'context/themes/shared.md',
      `---
title: Shared Name
type: record
---
Theme body.
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig(),
      baseDir: tempDir,
    });

    expect(result.errors).toEqual([]);
    expect(result.units.map((unit) => unit.id).sort()).toEqual([
      'context-studies',
      'context-studies-shared',
      'context-themes-shared',
    ]);
  });

  it('reports missing kind-required fields as strict lint errors', () => {
    write(
      'context/studies/missing-required.md',
      `---
title: Missing Source Study
type: study
methodology: Interviews
research_period: Q3
---
Body.
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig(),
      baseDir: tempDir,
    });

    expect(result.errors).toEqual([]);
    expect(result.warnings).toContainEqual(
      expect.objectContaining({
        code: 'missing-required-field',
        severity: 'error',
        field: 'source_url',
        unitId: 'context-studies-missing-required',
      }),
    );
  });

  it('reports invalid vocabulary values without mutating raw frontmatter', () => {
    write(
      'context/records/vendor.md',
      `---
title: Vendor Record
type: record
brand: Unknown Brand
---
Body.
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig({
        vocabularies: {
          brand: { values: ['Acme'] },
        },
      }),
      baseDir: tempDir,
    });

    expect(result.units[0].frontmatter.brand).toBe('Unknown Brand');
    expect(result.units[0].attributes.brand).toBe('Unknown Brand');
    expect(result.warnings).toContainEqual(
      expect.objectContaining({
        code: 'invalid-vocabulary',
        severity: 'error',
        field: 'brand',
      }),
    );
  });

  it('excludes conflicting duplicate IDs and reports all source paths', () => {
    write(
      'context/a.md',
      `---
id: shared
title: First
type: record
---
First.
`,
    );
    write(
      'context/b.md',
      `---
id: shared
title: Second
type: record
---
Second.
`,
    );

    const result = loadKnowledgeSync({
      sources: ['context/**/*.md'],
      config: makeConfig(),
      baseDir: tempDir,
    });

    expect(result.units).toEqual([]);
    expect(result.errors).toContainEqual(
      expect.objectContaining({
        code: 'duplicate-id',
        filePath: 'shared',
        message: expect.stringContaining('context/a.md, context/b.md'),
      }),
    );
  });

  it('build continues with valid records while excluding duplicate conflicts', async () => {
    write(
      'madrigal.config.yaml',
      `sources:
  - "context/**/*.md"
schema:
  id:
    field: id
    strategy: path
  kind:
    field: type
    default: record
  title:
    field: title
  relationships:
    wikilinks: true
kinds:
  record: {}
platforms:
  bundle:
    format: json-bundle
`,
    );
    write(
      'context/valid.md',
      `---
title: Valid Record
type: record
---
Valid.
`,
    );
    write(
      'context/duplicate-a.md',
      `---
id: duplicate
title: Duplicate A
type: record
---
A.
`,
    );
    write(
      'context/duplicate-b.md',
      `---
id: duplicate
title: Duplicate B
type: record
---
B.
`,
    );

    const result = await build({
      configPath: join(tempDir, 'madrigal.config.yaml'),
      baseDir: tempDir,
    });

    expect(result.success).toBe(true);
    expect(result.totalUnits).toBe(1);
    expect(result.loadErrors).toContainEqual(
      expect.objectContaining({ code: 'duplicate-id' }),
    );

    const bundle = JSON.parse(result.results[0].output) as {
      units: Array<{ id: string }>;
    };
    expect(bundle.units.map((unit) => unit.id)).toEqual(['context-valid']);
  });
});

import { describe, expect, it } from 'vitest';
import type { Enforcement } from '../enforcement.js';
import { findRelated } from '../propose.js';
import type { KnowledgeUnit } from '../schema/index.js';
import { BM25SearchAdapter } from '../search/adapter.js';
import { BM25Index, tokenize } from '../search/bm25.js';

function makeUnit(
  overrides: Partial<KnowledgeUnit> & { id: string; title: string },
): KnowledgeUnit {
  return {
    body: '',
    domain: 'content',
    kind: 'rule',
    tags: [],
    enforcement: 'should' as Enforcement,
    frontmatter: {},
    attributes: {},
    relationships: [],
    provenance: { origin: 'human-authored', confidence: 1.0 },
    ...overrides,
  };
}

// --- tokenize ---

describe('tokenize', () => {
  it('lowercases and splits on non-word characters', () => {
    expect(tokenize('Hello World')).toEqual(['hello', 'world']);
  });

  it('filters stop words', () => {
    expect(tokenize('this is a test of the system')).toEqual([
      'test',
      'system',
    ]);
  });

  it('filters tokens shorter than 2 characters', () => {
    // 'testing' is stemmed to 'test' by the English stemmer
    expect(tokenize('I am a b c testing')).toEqual(['test']);
  });

  it('handles empty input', () => {
    expect(tokenize('')).toEqual([]);
  });
});

// --- BM25Index ---

describe('BM25Index', () => {
  const units = [
    makeUnit({
      id: 'buttons',
      title: 'Button copy patterns',
      body: 'Buttons should use verb-object format. Keep labels short and actionable.',
      tags: ['buttons', 'ux-copy', 'components'],
    }),
    makeUnit({
      id: 'errors',
      title: 'Error message guidelines',
      body: 'Error messages should be helpful and suggest next steps. Avoid blaming the user.',
      tags: ['errors', 'ux-copy'],
    }),
    makeUnit({
      id: 'fdic',
      title: 'FDIC banking disclosure requirements',
      body: 'All banking interfaces must display FDIC disclosure. This is a legal compliance requirement for financial products.',
      tags: ['compliance', 'legal', 'banking'],
      enforcement: 'must' as Enforcement,
    }),
    makeUnit({
      id: 'voice',
      title: 'Voice and tone principles',
      body: 'Write with clarity and warmth. Be concise. Avoid jargon and corporate speak.',
      tags: ['voice', 'tone', 'style'],
    }),
    makeUnit({
      id: 'confirmation',
      title: 'Confirmation dialog copy',
      body: 'Confirmation dialogs should clearly state the action and its consequences. Use specific button labels.',
      tags: ['confirmation', 'modals', 'components'],
    }),
  ];

  it('returns empty results for empty query', () => {
    const index = new BM25Index(units);
    expect(index.search('')).toEqual([]);
  });

  it('returns empty results for empty corpus', () => {
    const index = new BM25Index([]);
    expect(index.search('buttons')).toEqual([]);
    expect(index.size).toBe(0);
  });

  it('ranks button-copy unit first for "button labels"', () => {
    const index = new BM25Index(units);
    const results = index.search('button labels');
    expect(results.length).toBeGreaterThan(0);
    expect(results[0].unit.id).toBe('buttons');
  });

  it('ranks FDIC unit first for "FDIC disclosure"', () => {
    const index = new BM25Index(units);
    const results = index.search('FDIC disclosure');
    expect(results[0].unit.id).toBe('fdic');
  });

  it('ranks error unit first for "error messages helpful"', () => {
    const index = new BM25Index(units);
    const results = index.search('error messages helpful');
    expect(results[0].unit.id).toBe('errors');
  });

  it('gives higher scores to title matches (title boost)', () => {
    const index = new BM25Index(units);
    // "voice" appears in the title of the voice unit
    const results = index.search('voice');
    expect(results[0].unit.id).toBe('voice');
  });

  it('finds units by tag content', () => {
    const index = new BM25Index(units);
    // "banking" is a tag on the FDIC unit
    const results = index.search('banking');
    expect(results.some((r) => r.unit.id === 'fdic')).toBe(true);
  });

  it('rare terms score higher than common terms', () => {
    const index = new BM25Index(units);
    // "fdic" appears only in one unit, "copy" appears in multiple
    const fdicResults = index.search('fdic');
    const copyResults = index.search('copy');
    // FDIC should have a higher top score (more discriminative)
    expect(fdicResults[0].score).toBeGreaterThan(copyResults[0].score);
  });

  it('respects limit parameter', () => {
    const index = new BM25Index(units);
    const results = index.search('copy components', 2);
    expect(results.length).toBeLessThanOrEqual(2);
  });

  it('reports correct size', () => {
    const index = new BM25Index(units);
    expect(index.size).toBe(5);
  });

  it('score() returns 0 for unknown unit ID', () => {
    const index = new BM25Index(units);
    expect(index.score('button', 'nonexistent')).toBe(0);
  });

  it('score() returns positive for matching unit', () => {
    const index = new BM25Index(units);
    expect(index.score('button labels', 'buttons')).toBeGreaterThan(0);
  });

  it('add() increases index size', () => {
    const index = new BM25Index(units);
    expect(index.size).toBe(5);
    index.add(
      makeUnit({
        id: 'new-unit',
        title: 'New unit about colors',
        body: 'Color contrast matters.',
        tags: ['colors'],
      }),
    );
    expect(index.size).toBe(6);
  });

  it('add() makes new unit searchable', () => {
    const index = new BM25Index(units);
    index.add(
      makeUnit({
        id: 'colors',
        title: 'Color contrast requirements',
        body: 'Ensure sufficient color contrast ratios for accessibility.',
        tags: ['colors', 'accessibility', 'contrast'],
      }),
    );
    const results = index.search('color contrast accessibility');
    expect(results[0].unit.id).toBe('colors');
  });

  it('does not add duplicate unit IDs', () => {
    const index = new BM25Index(units);
    index.add(units[0]); // already in index
    expect(index.size).toBe(5);
  });

  it('works with a single document', () => {
    const index = new BM25Index([units[0]]);
    const results = index.search('button');
    expect(results.length).toBe(1);
    expect(results[0].unit.id).toBe('buttons');
  });
});

// --- BM25SearchAdapter ---

describe('BM25SearchAdapter', () => {
  const units = [
    makeUnit({
      id: 'buttons',
      title: 'Button copy',
      body: 'Use verb-object labels.',
      domain: 'content',
      kind: 'rule',
      tags: ['buttons', 'ux-copy'],
      enforcement: 'should' as Enforcement,
    }),
    makeUnit({
      id: 'fdic',
      title: 'FDIC disclosure',
      body: 'Banking UI must show FDIC notice.',
      domain: 'content',
      kind: 'rule',
      tags: ['compliance', 'legal'],
      enforcement: 'must' as Enforcement,
    }),
    makeUnit({
      id: 'tokens',
      title: 'Color token naming',
      body: 'Use semantic color names.',
      domain: 'design-system',
      kind: 'glossary',
      brand: 'square',
      tags: ['tokens', 'colors'],
      enforcement: 'may' as Enforcement,
    }),
    makeUnit({
      id: 'voice',
      title: 'Voice principles',
      body: 'Be clear and warm.',
      domain: 'content',
      tags: ['voice'],
      enforcement: 'context' as Enforcement,
    }),
  ];

  describe('exactMatch', () => {
    it('filters by domain', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ domain: 'design-system' });
      expect(results).toHaveLength(1);
      expect(results[0].id).toBe('tokens');
    });

    it('filters by brand (null = global only)', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ brand: null });
      expect(results.every((u) => !u.brand)).toBe(true);
    });

    it('filters by brand (includes global)', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ brand: 'square' });
      expect(results.some((u) => u.id === 'tokens')).toBe(true);
      expect(results.some((u) => u.id === 'buttons')).toBe(true); // global
    });

    it('includes brand: "shared" units when filtering by a specific brand', async () => {
      const withShared = [
        ...units,
        makeUnit({ id: 'shared-rule', title: 'Shared rule', brand: 'shared' }),
        makeUnit({ id: 'global-rule', title: 'Global rule', brand: 'global' }),
      ];
      const adapter = new BM25SearchAdapter(withShared);
      const results = await adapter.exactMatch({ brand: 'square' });
      expect(results.some((u) => u.id === 'shared-rule')).toBe(true);
      expect(results.some((u) => u.id === 'global-rule')).toBe(true);
      expect(results.some((u) => u.id === 'tokens')).toBe(true); // square brand
      expect(results.some((u) => u.id === 'buttons')).toBe(true); // no brand = global
    });

    it('filters by enforcement', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ enforcement: ['must'] });
      expect(results).toHaveLength(1);
      expect(results[0].id).toBe('fdic');
    });

    it('filters by kind', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ kind: 'glossary' });
      expect(results).toHaveLength(1);
      expect(results[0].id).toBe('tokens');
    });

    it('filters by tags (all must match)', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({
        tags: ['compliance', 'legal'],
      });
      expect(results).toHaveLength(1);
      expect(results[0].id).toBe('fdic');
    });

    it('ranks by BM25 when textQuery is provided', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({
        textQuery: 'banking disclosure',
      });
      expect(results[0].id).toBe('fdic');
    });

    it('sorts by enforcement when no textQuery', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.exactMatch({ domain: 'content' });
      // must (fdic) should come before should (buttons) before context (voice)
      expect(results[0].enforcement).toBe('must');
    });
  });

  describe('semanticSearch', () => {
    it('returns scored results in descending order', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('button labels');
      expect(results.length).toBeGreaterThan(0);
      for (let i = 1; i < results.length; i++) {
        expect(results[i].score).toBeLessThanOrEqual(results[i - 1].score);
      }
    });

    it('normalizes top score to 1.0', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('button labels');
      expect(results[0].score).toBe(1);
    });

    it('filters by domain', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('color naming', {
        domain: 'design-system',
      });
      expect(results.every((r) => r.unit.domain === 'design-system')).toBe(
        true,
      );
    });

    it('includes brand: "shared" and "global" units when filtering by a specific brand', async () => {
      const withShared = [
        ...units,
        makeUnit({
          id: 'shared-rule',
          title: 'Shared copy rule',
          brand: 'shared',
          body: 'Use clear copy.',
        }),
        makeUnit({
          id: 'global-rule',
          title: 'Global copy rule',
          brand: 'global',
          body: 'Use clear copy.',
        }),
      ];
      const adapter = new BM25SearchAdapter(withShared);
      const results = await adapter.semanticSearch('copy guidelines', {
        brand: 'square',
      });
      const ids = results.map((r) => r.unit.id);
      expect(ids).toContain('shared-rule');
      expect(ids).toContain('global-rule');
    });

    it('filters by minEnforcement', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('copy guidelines', {
        minEnforcement: 'should',
      });
      // should only include must and should, not may or context
      expect(
        results.every(
          (r) =>
            r.unit.enforcement === 'must' || r.unit.enforcement === 'should',
        ),
      ).toBe(true);
    });

    it('filters by minScore', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('button labels', {
        minScore: 0.5,
      });
      expect(results.every((r) => r.score >= 0.5)).toBe(true);
    });

    it('respects limit', async () => {
      const adapter = new BM25SearchAdapter(units);
      const results = await adapter.semanticSearch('copy', { limit: 1 });
      expect(results.length).toBeLessThanOrEqual(1);
    });
  });
});

